import { test } from "node:test";
import assert from "node:assert/strict";
import { orderTotal } from "../src/order-total.js";

test("applies tax to the full subtotal when there is no discount", () => {
  assert.equal(orderTotal(100, { taxRate: 0.08 }), 108);
});

test("applies a flat discount before tax", () => {
  assert.equal(orderTotal(100, { taxRate: 0.1, discount: 20 }), 88);
});

test("returns the subtotal when tax and discount are both omitted", () => {
  assert.equal(orderTotal(50), 50);
});

test("rounds to two decimal places", () => {
  assert.equal(orderTotal(10, { taxRate: 0.0725 }), 10.73);
});

test("throws when subtotal is negative", () => {
  assert.throws(() => orderTotal(-5), RangeError);
});

test("throws when taxRate is negative", () => {
  assert.throws(() => orderTotal(100, { taxRate: -0.1 }), RangeError);
});

test("throws when discount is negative", () => {
  assert.throws(() => orderTotal(100, { discount: -5 }), RangeError);
});

test("throws when discount exceeds subtotal", () => {
  assert.throws(() => orderTotal(50, { discount: 60 }), RangeError);
});
